//! C-ABI FFI wrapper around the `age` crate (rage library).
//!
//! Exposes a small, stable C interface so the FileEncryptor C++ CLI can call into
//! the Rust implementation of hybrid asymmetric encryption:
//!   - A random per-file symmetric key is generated by `age`.
//!   - The file is encrypted with that key (ChaCha20-Poly1305 stream).
//!   - The symmetric key is then wrapped to one or more X25519 recipients
//!     (the asymmetric part).
//!
//! All exported functions are `#[no_mangle] extern "C"`, panic-safe (panics are
//! caught and reported as error strings instead of unwinding across the FFI
//! boundary), and never leak secrets through their signatures.

#![allow(clippy::missing_safety_doc)]

use std::ffi::{c_char, c_int, CStr, CString};
use std::fs::File;
use std::ptr;
use std::str::FromStr;

use age::{Decryptor, Encryptor, Identity, Recipient};
use age::x25519::{Identity as X25519Identity, Recipient as X25519Recipient};
use secrecy::ExposeSecret;

/// Convert a Rust `String` into an owned, nul-terminated C string pointer.
/// Returns a null pointer if the string contained an interior NUL (should not
/// happen for base32/bech32 age keys).
fn to_cstr(s: String) -> *mut c_char {
    match CString::new(s) {
        Ok(c) => c.into_raw(),
        Err(_) => ptr::null_mut(),
    }
}

/// Write an error message into `*err_out` (allocated, freed by caller via
/// `fe_age_free_string`). No-op if `err_out` is null.
fn set_err(err_out: *mut *mut c_char, msg: String) {
    if !err_out.is_null() {
        unsafe { *err_out = to_cstr(msg); }
    }
}

/// Free a string previously returned by this library.
///
/// # Safety
/// `s` must be either null or a pointer returned by one of the `fe_age_*`
/// functions (and not freed yet).
#[no_mangle]
pub unsafe extern "C" fn fe_age_free_string(s: *mut c_char) {
    if !s.is_null() {
        drop(CString::from_raw(s));
    }
}

/// Return the version of this FFI crate (matches the wrapped `age` version).
#[no_mangle]
pub extern "C" fn fe_age_get_version() -> *mut c_char {
    to_cstr(env!("CARGO_PKG_VERSION").to_string())
}

/// Generate an X25519 keypair.
///
/// On success returns `0` and writes the bech32 recipient (`age1...`) into
/// `*pub_out` and the secret identity (`AGE-SECRET-KEY-...`) into `*priv_out`.
/// Both must be freed by the caller with `fe_age_free_string`.
///
/// # Safety
/// `pub_out` and `priv_out` must be valid pointers to `char*`.
#[no_mangle]
pub unsafe extern "C" fn fe_age_generate_keypair(
    pub_out: *mut *mut c_char,
    priv_out: *mut *mut c_char,
) -> c_int {
    if pub_out.is_null() || priv_out.is_null() {
        return 1;
    }
    let run = || -> Result<(), String> {
        let sk = X25519Identity::generate();
        let pk = sk.to_public();
        unsafe {
            *pub_out = to_cstr(format!("{}", pk));
            let sk_str = sk.to_string().expose_secret().to_string();
            *priv_out = to_cstr(sk_str);
        }
        Ok(())
    };
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(run)) {
        Ok(Ok(())) => 0,
        Ok(Err(_)) => 1,
        Err(_) => 1,
    }
}

/// Parse a C array of recipient strings (`age1...`, optionally prefixed with
/// `publickey:`) into a list of boxed `Recipient`s. Blank lines and `#` comments
/// are skipped.
fn parse_recipients(
    ptr: *const *const c_char,
    len: usize,
) -> Result<Vec<Box<dyn Recipient>>, String> {
    if ptr.is_null() {
        return Err("null recipients array".into());
    }
    let mut out: Vec<Box<dyn Recipient>> = Vec::new();
    for i in 0..len {
        let c = unsafe { *ptr.add(i) };
        if c.is_null() {
            continue;
        }
        let s = unsafe { CStr::from_ptr(c) }.to_string_lossy().into_owned();
        let line = s.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let key = match line.strip_prefix("publickey:") {
            Some(rest) => rest.trim(),
            None => line,
        };
        let r = X25519Recipient::from_str(key)
            .map_err(|e| format!("invalid recipient `{}`: {}", key, e))?;
        out.push(Box::new(r));
    }
    if out.is_empty() {
        return Err("no valid recipient found".into());
    }
    Ok(out)
}

/// Parse a C array of identity strings (`AGE-SECRET-KEY-...`, optionally
/// prefixed with `identity:`) into a list of boxed `Identity`s.
fn parse_identities(
    ptr: *const *const c_char,
    len: usize,
) -> Result<Vec<Box<dyn Identity>>, String> {
    if ptr.is_null() {
        return Err("null identities array".into());
    }
    let mut out: Vec<Box<dyn Identity>> = Vec::new();
    for i in 0..len {
        let c = unsafe { *ptr.add(i) };
        if c.is_null() {
            continue;
        }
        let s = unsafe { CStr::from_ptr(c) }.to_string_lossy().into_owned();
        let line = s.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let key = match line.strip_prefix("identity:") {
            Some(rest) => rest.trim(),
            None => line,
        };
        let id = X25519Identity::from_str(key)
            .map_err(|e| format!("invalid identity `{}`: {}", key, e))?;
        out.push(Box::new(id));
    }
    if out.is_empty() {
        return Err("no valid identity found".into());
    }
    Ok(out)
}

/// Encrypt `in_path` to `out_path` for the given recipients (hybrid: random
/// file key wrapped to each X25519 recipient). Returns `0` on success, `1` on
/// error (with a message in `*err_out`, freed by caller).
///
/// # Safety
/// All pointer arguments must be valid (or null where documented). Strings are
/// read as UTF-8 paths.
#[no_mangle]
pub unsafe extern "C" fn fe_age_encrypt_file(
    recipients: *const *const c_char,
    recipients_len: usize,
    in_path: *const c_char,
    out_path: *const c_char,
    err_out: *mut *mut c_char,
) -> c_int {
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| -> Result<c_int, String> {
        if in_path.is_null() || out_path.is_null() {
            return Err("null path argument".into());
        }
        let in_s = unsafe { CStr::from_ptr(in_path) }.to_string_lossy().into_owned();
        let out_s = unsafe { CStr::from_ptr(out_path) }.to_string_lossy().into_owned();

        let recips = parse_recipients(recipients, recipients_len)?;
        let refs: Vec<&dyn Recipient> = recips.iter().map(|b| b.as_ref()).collect();
        let encryptor = Encryptor::with_recipients(refs.into_iter())
            .map_err(|e| format!("age encryptor init failed: {}", e))?;

        let mut input =
            File::open(&in_s).map_err(|e| format!("open input `{}`: {}", in_s, e))?;
        let output =
            File::create(&out_s).map_err(|e| format!("create output `{}`: {}", out_s, e))?;

        let mut writer = encryptor
            .wrap_output(output)
            .map_err(|e| format!("age wrap_output failed: {}", e))?;
        std::io::copy(&mut input, &mut writer).map_err(|e| format!("read/write failed: {}", e))?;
        writer.finish().map_err(|e| format!("age finish failed: {}", e))?;
        Ok(0)
    }));

    match result {
        Ok(Ok(_)) => 0,
        Ok(Err(e)) => {
            set_err(err_out, e);
            1
        }
        Err(_) => {
            set_err(err_out, "panic in fe_age_encrypt_file".into());
            1
        }
    }
}

/// Decrypt `in_path` to `out_path` using the given identities. Returns `0` on
/// success, `1` on error (with a message in `*err_out`, freed by caller).
///
/// # Safety
/// All pointer arguments must be valid (or null where documented). Strings are
/// read as UTF-8 paths.
#[no_mangle]
pub unsafe extern "C" fn fe_age_decrypt_file(
    identities: *const *const c_char,
    identities_len: usize,
    in_path: *const c_char,
    out_path: *const c_char,
    err_out: *mut *mut c_char,
) -> c_int {
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| -> Result<c_int, String> {
        if in_path.is_null() || out_path.is_null() {
            return Err("null path argument".into());
        }
        let in_s = unsafe { CStr::from_ptr(in_path) }.to_string_lossy().into_owned();
        let out_s = unsafe { CStr::from_ptr(out_path) }.to_string_lossy().into_owned();

        let idents = parse_identities(identities, identities_len)?;
        let irefs: Vec<&dyn Identity> = idents.iter().map(|b| b.as_ref()).collect();

        let input =
            File::open(&in_s).map_err(|e| format!("open input `{}`: {}", in_s, e))?;
        let decryptor = Decryptor::new(input)
            .map_err(|e| format!("age header parse failed: {}", e))?;
        let mut reader = decryptor
            .decrypt(irefs.into_iter())
            .map_err(|e| format!("decryption failed (wrong identity or corrupted file): {}", e))?;

        let mut output =
            File::create(&out_s).map_err(|e| format!("create output `{}`: {}", out_s, e))?;
        std::io::copy(&mut reader, &mut output).map_err(|e| format!("read/write failed: {}", e))?;
        Ok(0)
    }));

    match result {
        Ok(Ok(_)) => 0,
        Ok(Err(e)) => {
            set_err(err_out, e);
            1
        }
        Err(_) => {
            set_err(err_out, "panic in fe_age_decrypt_file".into());
            1
        }
    }
}
